// Compile-time contract between the hand-written view types (types.ts) and the API's OpenAPI document
// (openapi.gen.ts, generated by `npm run api:types` from a running backend). Every field a screen reads
// must exist in the API's response schema: a renamed or removed field fails `npm run typecheck` here,
// naming the type and the field. Fields the API sends but the screens don't use are fine.
//
// Not covered: the My Health tabs (the API declares them as plain objects) and mock-only fields.
import type { components } from "./openapi.gen";
import type * as T from "./types";

type S = components["schemas"];

/** Fields of H that the API schema A doesn't have; `never` when H fits. */
type Missing<H, A> = Exclude<keyof H, keyof A>;
/** Compiles only when its argument is `never`; the error message lists the stray field names. */
type Fits<M extends never> = M;

export type Contract = [
  Fits<Missing<T.Me, S["Me"]>>,
  Fits<Missing<T.AccountProfile, S["Account"]>>,
  Fits<Missing<T.Dashboard, S["Dashboard"]>>,
  Fits<Missing<T.MetricSummary, S["MetricSummary"]>>,
  Fits<Missing<T.Series, S["Series"]>>,
  Fits<Missing<T.SeriesPoint, S["SeriesPoint"]>>,
  Fits<Missing<T.Targets, S["Targets"]>>,
  Fits<Missing<T.Reading, S["TabReading"]>>, // /me/health/latest sends the same minus the optional period wording
  Fits<Missing<T.Device, S["DeviceOut"]>>,
  Fits<Missing<T.Workout, S["WorkoutOut"]>>,
  Fits<Missing<T.Training, S["Training"]>>,
  Fits<Missing<T.TrainingSession, S["TrainingSession"]>>,
  Fits<Missing<T.TrainingWeek, S["TrainingWeek"]>>,
  Fits<Missing<T.MuscleGroupSets, S["MuscleGroupSets"]>>,
  Fits<Missing<T.PersonalRecord, S["PersonalRecord"]>>,
  Fits<Missing<T.PlannedSession, S["PlannedSession"]>>,
  Fits<Missing<T.NutritionDay, S["NutritionDay"]>>,
  Fits<Missing<T.Meal, S["Meal"]>>,
  Fits<Missing<T.Share, S["Share"]>>,
  Fits<Missing<T.SharedWithMe, S["SharedWithMe"]>>,
  Fits<Missing<T.AccessLogEntry, S["AccessLogEntry"]>>,
  Fits<Missing<T.PrivacySettings, S["Privacy"]>>,
  Fits<Missing<T.FamilyMember, S["FamilyMember"]>>,
  Fits<Missing<T.Goal, S["GoalProgress"]>>,
  Fits<Missing<T.GoalsOverview, S["GoalsOverview"]>>,
  Fits<Missing<T.TrackedGoal, S["TrackedGoal"]>>,
  Fits<Missing<T.Medication, S["TodayDose"]>>,
  Fits<Missing<T.MedicationsOverview, S["MedicationsOverview"]>>,
  Fits<Missing<T.Prescription, S["Prescription"]>>,
  Fits<Missing<T.Appointment, S["Appointment"]>>,
  Fits<Missing<T.EmergencyProfile, S["EmergencyProfile"]>>,
  Fits<Missing<T.RecordsOverview, S["RecordsOverview"]>>,
  Fits<Missing<T.HealthRecord, S["HealthRecord"]>>,
  Fits<Missing<T.RecordShare, S["RecordShare"]>>,
  Fits<Missing<T.LabPanel, S["LabPanel"]>>,
  Fits<Missing<T.LabResult, S["LabResult"]>>,
  Fits<Missing<T.LatestLab, S["LatestLab"]>>,
  Fits<Missing<T.AppNotification, S["Notification"]>>,
  Fits<Missing<T.Library, S["Library"]>>,
  Fits<Missing<T.Article, S["Article"]>>,
  Fits<Missing<T.HealthOverview, S["HealthOverview"]>>,
  Fits<Missing<T.Insight, S["Insight"]>>,
  Fits<Missing<T.FoodHit, S["FoodOut"]>>,
  Fits<Missing<T.GoalMetricOption, S["GoalMetric"]>>,
  Fits<Missing<T.ConditionItem, S["Condition"]>>,
];
